INSERT INTO public.products (name, description, price, image_url, category_slug, stock, is_active, is_popular, allergens, storage_method, shelf_life) VALUES
  ('세미나 답례 30개입', '세미나, 컨퍼런스용 소포장 화과자. 깔끔한 개별 포장으로 위생적입니다.', 120000, 'https://picsum.photos/seed/wagashi17/600/600', 'corporate', 30, true, false, '백앙금, 한천, 천연색소', '냉장', '제조일로부터 5일'),
  ('VIP 감사 선물 세트', 'VIP 고객을 위한 최고급 화과자 선물. 금박 장식과 함께 특별함을 전달합니다.', 150000, 'https://picsum.photos/seed/wagashi18/600/600', 'corporate', 10, true, false, '찹쌀가루, 팥앙금, 백앙금, 금박, 천연색소', '냉장', '제조일로부터 5일'),
  ('벚꽃 봄 한정', '봄바람에 흩날리는 벚꽃을 담은 시즌 한정 화과자. 매년 3-5월에만 만나실 수 있습니다.', 38000, 'https://picsum.photos/seed/wagashi19/600/600', 'seasonal', 45, true, true, '백앙금, 벚꽃잎, 한천, 천연색소', '냉장', '제조일로부터 5일'),
  ('수박 여름 한정', '시원한 수박 모양의 여름 한정 화과자. 달콤하고 시원한 맛이 여름을 더욱 상쾌하게 합니다.', 35000, 'https://picsum.photos/seed/wagashi20/600/600', 'seasonal', 40, true, false, '백앙금, 수박분말, 한천, 천연색소', '냉장', '제조일로부터 5일'),
  ('단풍 가을 한정', '가을 단풍을 담은 시즌 한정판. 은행, 단풍잎 모양의 섬세한 화과자입니다.', 42000, 'https://picsum.photos/seed/wagashi21/600/600', 'seasonal', 35, true, false, '찹쌀가루, 백앙금, 단호박, 천연색소', '냉장', '제조일로부터 5일'),
  ('알찬 2종 세트', '인기 화과자 2종 구성 미니 선물 세트. 가벼운 감사 인사에 적합합니다.', 22000, 'https://picsum.photos/seed/wagashi22/600/600', 'gift-set', 60, true, false, '찹쌀가루, 팥앙금, 백앙금, 천연색소', '냉장', '제조일로부터 5일'),
  ('정성 5종 선물 세트', '다섯 가지 맛과 모양을 골고루 담은 인기 선물 세트. 어떤 상황에서도 활용할 수 있는 만능 선물입니다.', 48000, 'https://picsum.photos/seed/wagashi23/600/600', 'gift-set', 35, true, true, '찹쌀가루, 팥앙금, 백앙금, 흑임자, 천연색소', '냉장', '제조일로부터 5일'),
  ('프리미엄 10종 세트', '열 가지 프리미엄 화과자를 한 상자에 담은 최고급 선물 세트. 특별한 날에 어울리는 선물입니다.', 89000, 'https://picsum.photos/seed/wagashi24/600/600', 'gift-set', 15, true, true, '찹쌀가루, 팥앙금, 백앙금, 말차, 유자, 흑임자, 천연색소', '냉장', '제조일로부터 5일');
